<?php
if(!isset($user,$pickerAction,$pickerParams)){http_response_code(403);exit;}
$query=input_text($_GET,'q');if(!valid_text($query,100,false)){http_response_code(400);exit('Pencarian terlalu panjang.');}
$parentPicker=($kind??'')==='orang_tua';
$pattern='%'.str_replace(['!','%','_'],['!!','!%','!_'],$query).'%';
$pickerBind=['nama'=>$pattern,'tempat'=>$pattern];
$pickerFrom=" FROM pkl_placements p JOIN siswa s ON s.id=p.siswa_id WHERE s.nama LIKE :nama ESCAPE '!' OR ".($parentPicker?'p.kelas':'p.tempat_pkl')." LIKE :tempat ESCAPE '!'";
$pickerTotal=(int)panel_query('SELECT COUNT(*)'.$pickerFrom,$pickerBind)->fetchColumn();$pickerPages=max(1,(int)ceil($pickerTotal/10));$pickerPage=min($pickerPages,positive_id($_GET['page']??'1')??1);
$placements=panel_query('SELECT p.id,p.tanggal_mulai,p.tanggal_selesai,p.tempat_pkl,p.kelas,p.jurusan,s.nama'.$pickerFrom.' ORDER BY p.tanggal_mulai DESC,p.id DESC LIMIT :limit OFFSET :offset',$pickerBind+['limit'=>10,'offset'=>($pickerPage-1)*10])->fetchAll();
?>
<p class="schedule-picker-help"><?= $parentPicker?'Pilih siswa yang orang tua/walinya diundang rapat di sekolah. Daftar mengikuti penempatan PKL yang tersedia.':'Pilih satu atau beberapa siswa. Waktu, lokasi, dan agenda diisi sekali; setiap siswa mendapat catatan jadwal terpisah.' ?></p>
<form class="filter-form card" method="get" action="<?= e(base_url($pickerAction)) ?>"><?php foreach($pickerParams as $key=>$value): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e($value) ?>"><?php endforeach; ?><label for="schedule-placement-q"><span><?= panel_icon('search') ?> <?= $parentPicker?'Cari nama siswa atau kelas':'Cari siswa atau tempat PKL' ?></span><input id="schedule-placement-q" name="q" type="search" maxlength="100" value="<?= e($query) ?>" placeholder="<?= $parentPicker?'Nama siswa / kelas':'Nama siswa / perusahaan tempat PKL' ?>"></label><button type="submit"><?= panel_icon('search') ?> Cari</button><?php if($query!==''): ?><a href="<?= e(base_url($pickerAction.'?'.http_build_query($pickerParams))) ?>">Reset</a><?php endif; ?></form>
<div class="schedule-picker-count"><?= $pickerTotal ?> penempatan &middot; Halaman <?= $pickerPage ?> dari <?= $pickerPages ?></div>
<?php $selectionKey='bkk-schedule:'.base_url('panel/pkl/').':'.$user['id'].':'.$kind;$resetSelection=!empty($_SESSION['schedule_selection_clear'][$kind]);unset($_SESSION['schedule_selection_clear'][$kind]); ?>
<form class="schedule-multi-picker" method="post" data-storage-key="<?= e($selectionKey) ?>" data-reset="<?= $resetSelection?'1':'0' ?>"><?= csrf_field() ?><input type="hidden" name="aksi" value="pilih_banyak"><input type="hidden" name="jenis" value="<?= e($kind) ?>">
<div class="schedule-multi-toolbar"><strong id="schedule-selected-count" role="status">0 siswa dipilih</strong><button type="button" data-schedule-check="all">Pilih halaman ini</button><button type="button" data-schedule-check="none">Kosongkan semua</button><button type="submit"><?= panel_icon('next') ?> Lanjutkan pilihan</button><small>Pilihan antarhalaman/pencarian tetap tersimpan di tab ini. Maksimal 50 penempatan.</small></div>
<div class="table-scroll schedule-picker-sheet" data-vertical-list tabindex="0" role="region" aria-label="Pilih penempatan siswa untuk jadwal"><table><thead><tr><th>Siswa</th><th><?= $parentPicker?'Kelas':'Tempat PKL' ?></th><th><?= $parentPicker?'Jurusan':'Periode PKL' ?></th><th>Tindakan</th></tr></thead><tbody><?php foreach($placements as $item): ?><tr><td><label class="schedule-multi-choice"><input type="checkbox" name="placement_ids[]" value="<?= (int)$item['id'] ?>"><strong><?= e($item['nama']) ?></strong></label></td><td><?= e($parentPicker?$item['kelas']:$item['tempat_pkl']) ?></td><td><?= e($parentPicker?$item['jurusan']:$item['tanggal_mulai'].' - '.$item['tanggal_selesai']) ?></td><td><a class="schedule-choose" href="<?= e(base_url($pickerAction.'?'.http_build_query($pickerParams+['placement_id'=>$item['id']]))) ?>"><?= panel_icon('next') ?> Pilih siswa ini</a></td></tr><?php endforeach; ?><?php if(!$placements): ?><tr><td colspan="4" class="empty-panel"><?= $query!==''?'Tidak ada hasil. Ubah kata kunci atau reset pencarian.':'Belum ada penempatan. Buat penempatan PKL siswa terlebih dahulu.' ?><?php if($query===''): ?><p><a href="<?= e(base_url('panel/pkl/form.php')) ?>">Buat penempatan PKL</a></p><?php endif; ?></td></tr><?php endif; ?></tbody></table></div></form>
<?php if($pickerPages>1):$start=max(1,min($pickerPage-4,$pickerPages-9));$end=min($pickerPages,$start+9); ?><nav class="pagination" aria-label="Halaman penempatan siswa"><?php if($pickerPage>1): ?><a href="<?= e(base_url($pickerAction.'?'.http_build_query($pickerParams+['q'=>$query,'page'=>$pickerPage-1]))) ?>">Sebelumnya</a><?php endif; ?><?php for($n=$start;$n<=$end;$n++): ?><a href="<?= e(base_url($pickerAction.'?'.http_build_query($pickerParams+['q'=>$query,'page'=>$n]))) ?>" <?= $n===$pickerPage?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?><?php if($pickerPage<$pickerPages): ?><a href="<?= e(base_url($pickerAction.'?'.http_build_query($pickerParams+['q'=>$query,'page'=>$pickerPage+1]))) ?>">Berikutnya</a><?php endif; ?></nav><?php endif; ?>
